password" show-password :placeholder="dialog.editing ? '留空则不修改' : '至少 12 位'" /></el-form-item><el-form-item label="账号状态"><el-switch v-model="dialog.form.enabled" active-text="启用" inactive-text="停用" /></el-form-item><el-form-item label="接单权限"><el-switch v-model="dialog.form.process" active-text="允许" inactive-text="禁止" /></el-form-item><el-form-item label="配送权限"><el-switch v-model="dialog.form.deliver" active-text="允许" inactive-text="禁止" /></el-form-item><el-alert title="外包账号只能查看分配给自己的订单，不会看到 KTV 经营数据。" type="info" :closable="false" /></template></el-form><template #footer><el-button @click="dialog.open = false">取消</el-button><el-button type="primary" :loading="dialog.saving" @click="saveRow">保存</el-button></template></el-dialog>
