Number(scope.row.price || 0).toFixed(2) }}</template></el-table-column></el-table><h4>订单进度</h4><el-timeline><el-timeline-item v-for="event in detail.order.events || []" :key="event.time + event.label" :timestamp="formatTime(event.time || event.at)">{{ event.label }}</el-timeline-item></el-timeline><el-alert v-if="detail.order.refundReason" :title="'退款原因：' + detail.order.refundReason" :description="detail.order.refundReviewReason ? '审批说明：' + detail.order.refundReviewReason : '等待管理员审批'" type="warning" :closable="false" /></template><el-empty v-else description="订单不存在" /><template #footer><el-button v-if="detail.order.refundStatus === 'PENDING'" type="primary" @click="reviewRefundRequest(detail.order, true)">同意退款</el-button><el-button v-if="detail.order.refundStatus === 'PENDING'" type="danger" @click="reviewRefundRequest(detail.order, false)">拒绝退款</el-button><el-button @click="detail.open = false">关闭</el-button></template></el-dialog>
