<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { House, Shop, List, User, SwitchButton, Refresh, Box, Wallet, Food, CreditCard, Search } from '@element-plus/icons-vue'
import { getKtvState, getKtvOrders, exportKtvOrders, batchOrderAction, getKtvOrderDetail, reassignKtvOrder, ktvLogout, updateProduct, deleteProduct, updateRoom, deleteRoom, generateRoomQRCode, createAccount, updateAccount, deleteAccount, createCategory, renameCategory as renameCategoryApi, deleteCategory, reviewRefund, uploadKtvImage } from '@/api/ktv'

const router = useRouter(); const activeTab = ref('overview'); const now = ref(''); let timer
const state = reactive({ products: [], categories: [], rooms: [], accounts: [], orders: [], orderTotal: 0, subject: '' }); const listFilter = reactive({ keyword: '', status: '' }); const appliedListFilter = reactive({ keyword: '', status: '' }); const orderPage = reactive({ items: [], total: 0, page: 1, pageSize: 10, keyword: '', status: '', room: '', supplierId: '', paid: undefined, paymentMode: '', refundStatus: '', minTotal: undefined, maxTotal: undefined, timeRange: [] }); const paymentFilter = reactive({ keyword: '', mode: '', refundStatus: '' }); const appliedPaymentFilter = reactive({ keyword: '', mode: '', refundStatus: '' }); const paymentPage = reactive({ items: [], total: 0, page: 1, pageSize: 10 }); const selectedOrderIds = ref([]); const exporting = ref(false); const batchLoading = ref(false); const dialog = reactive({ open: false, kind: '', title: '', form: {}, originalId: '', editing: false, saving: false }); const categoryDialog = reactive({ open: false, form: { name: '' }, saving: false }); const qr = reactive({ open: false, room: '', url: '', type: 'mini' }); const uploadInput = ref(); const detail = reactive({ open: false, loading: false, order: {}, reassignSupplierId: '' })
function apiErrorMessage(error, fallback) { const response = error?.response; const data = response?.data || {}; if (response?.status === 401) return '登录已过期，请重新登录'; if (response?.status === 403) return data.message || data.msg || '当前账号没有管理员权限'; return data.message || data.msg || error?.message || fallback }
const tabs = [{ key: 'overview', label: '运营概览', icon: House }, { key: 'rooms', label: '包厢管理', icon: Box }, { key: 'foods', label: '餐品管理', icon: Food }, { key: 'orders', label: '订单管理', icon: List }, { key: 'accounts', label: '账号与权限', icon: User }, { key: 'payments', label: '支付记录', icon: CreditCard }]
const currentTab = computed(() => tabs.find(item => item.key === activeTab.value) || tabs[0]); const rooms = computed(() => state.rooms); const orders = computed(() => state.orders); const categories = computed(() => Array.from(new Set([...(state.categories || []), ...state.products.map(item => item.category).filter(Boolean)])))
const orderStatusOptions = [{ value: 'unpaid', label: '待支付' }, { value: 'pending', label: '待接单' }, { value: 'preparing', label: '制作中' }, { value: 'delivering', label: '配送中' }, { value: 'completed', label: '已完成' }, { value: 'closed', label: '已关闭' }, { value: 'cancelled', label: '已取消' }, { value: 'refunding', label: '退款处理中' }, { value: 'refunded', label: '已退款' }]; const refundOptions = [{ value: 'PENDING', label: '退款待审批' }, { value: 'PROCESSING', label: '退款处理中' }, { value: 'SUCCESS', label: '已退款' }, { value: 'REJECTED', label: '退款已拒绝' }]
const statCards = computed(() => [{ label: '包厢总数', value: state.rooms.length, hint: `${state.rooms.filter(x => x.bound).length} 个已启用`, icon: Box, tone: 'blue' }, { label: '订单总数', value: state.orderTotal, hint: '实时同步', icon: List, tone: 'orange' }, { label: '待处理订单', value: state.orders.filter(x => ['pending', 'preparing', 'delivering'].includes(x.status)).length, hint: '请及时跟进', icon: Wallet, tone: 'green' }, { label: '在售餐品', value: state.products.filter(x => x.onSale).length, hint: `${state.products.length} 个餐品`, icon: Shop, tone: 'purple' }])
const columnsByTab = { rooms: [{ prop: 'id', label: '包厢编号' }, { prop: 'bound', label: '状态' }, { prop: 'qrcodeUrl', label: '二维码', width: 160 }], foods: [{ prop: 'id', label: '餐品编号', width: 140 }, { prop: 'name', label: '餐品名称', width: 180 }, { prop: 'category', label: '分类' }, { prop: 'price', label: '售价' }, { prop: 'onSale', label: '状态' }], orders: [{ prop: 'id', label: '订单号' }, { prop: 'room', label: '包厢' }, { prop: 'supplierId', label: '接单账号' }, { prop: 'totalCents', label: '金额' }, { prop: 'status', label: '订单状态' }, { prop: 'paid', label: '支付' }, { prop: 'refundStatus', label: '退款状态', width: 130 }, { prop: 'createdAt', label: '下单时间', width: 180 }], accounts: [{ prop: 'id', label: '账号' }, { prop: 'name', label: '名称', width: 180 }, { prop: 'enabled', label: '状态' }, { prop: 'process', label: '接单权限' }, { prop: 'deliver', label: '配送权限' }], payments: [{ prop: 'id', label: '订单号' }, { prop: 'room', label: '包厢' }, { prop: 'supplierId', label: '接单账号' }, { prop: 'totalCents', label: '金额' }, { prop: 'paid', label: '支付状态' }, { prop: 'paymentMode', label: '支付方式' }, { prop: 'refundStatus', label: '退款状态', width: 150 }, { prop: 'createdAt', label: '时间', width: 180 }] }
const columns = computed(() => columnsByTab[activeTab.value] || []); const visibleRows = computed(() => { if (activeTab.value === 'orders') return orderPage.items; if (activeTab.value === 'payments') return paymentPage.items; const keyword = appliedListFilter.keyword.trim().toLowerCase(); const status = appliedListFilter.status; const source = ['accounts', 'permissions'].includes(activeTab.value) ? state.accounts : activeTab.value === 'rooms' ? state.rooms : state.products; return source.filter(row => { const text = `${row.id || ''}${row.name || ''}`.toLowerCase(); if (keyword && !text.includes(keyword)) return false; if (!status) return true; return activeTab.value === 'rooms' ? (status === 'enabled' ? row.bound : !row.bound) : activeTab.value === 'foods' ? (status === 'onSale' ? row.onSale : !row.onSale) : (status === 'enabled' ? row.enabled : !row.enabled) }) })
function formatNow(date = new Date()) { const parts = new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).formatToParts(date); const values = Object.fromEntries(parts.filter(x => x.type !== 'literal').map(x => [x.type, x.value])); return `${values.year}-${values.month}-${values.day} ${values.hour}:${values.minute}:${values.second}` }; function formatTime(value) { if (!value) return '-'; const text = String(value); const date = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text) ? new Date(text.replace(' ', 'T') + '+08:00') : new Date(text); return Number.isNaN(date.getTime()) ? text : formatNow(date) }
function statusLabel(status) { return ({ unpaid: '待支付', pending: '待接单', preparing: '制作中', delivering: '配送中', completed: '已完成', closed: '已关闭', cancelled: '已取消', refunding: '退款处理中', refunded: '已退款' })[status] || status || '-' }; function statusType(status) { return ({ unpaid: 'info', pending: 'warning', preparing: 'primary', delivering: 'success', completed: 'success', closed: 'info', cancelled: 'info', refunding: 'warning', refunded: 'success' })[status] || '' }; function refundLabel(status) { return ({ PENDING: '待审批', PROCESSING: '处理中', SUCCESS: '已退款', REJECTED: '已拒绝' })[status] || '无申请' }; function refundType(status) { return ({ PENDING: 'warning', PROCESSING: 'primary', SUCCESS: 'success', REJECTED: 'danger' })[status] || 'info' }
function toCents(value) { return value === undefined || value === null || value === '' ? undefined : Math.round(Number(value) * 100) }
function handleOrderSelection(rows) { selectedOrderIds.value = rows.map(row => String(row.id)) }
function exportFilterParams() { return { keyword: orderPage.keyword, status: orderPage.status, room: orderPage.room, supplierId: orderPage.supplierId, paid: orderPage.paid, paymentMode: orderPage.paymentMode, refundStatus: orderPage.refundStatus, minTotalCents: toCents(orderPage.minTotal), maxTotalCents: toCents(orderPage.maxTotal), startTime: orderPage.timeRange?.[0] || '', endTime: orderPage.timeRange?.[1] || '' } }
async function exportOrders() { exporting.value = true; try { const { data } = await exportKtvOrders(exportFilterParams()); const blob = data instanceof Blob ? data : new Blob([data], { type: 'text/csv;charset=utf-8' }); if (!blob.size) throw new Error('没有可导出的订单'); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `KTV订单-${formatNow().replace(/[-: ]/g, '')}.csv`; link.click(); URL.revokeObjectURL(url); ElMessage.success('订单导出成功') } catch (error) { ElMessage.error(error.response?.data?.message || error.message || '订单导出失败') } finally { exporting.value = false } }
async function batchAction(action) { if (!selectedOrderIds.value.length) return ElMessage.warning('请先勾选订单'); const approved = action === 'reject-refund'; try { const prompt = await ElMessageBox.prompt(approved ? '请输入批量拒绝退款原因' : '确认关闭已超过 30 分钟的未支付订单？可处理订单之外的选择会自动跳过。', approved ? '批量拒绝退款' : '批量关闭订单', { inputValue: approved ? '管理员批量拒绝退款申请' : '', inputValidator: value => !approved || (value && value.trim().length <= 200) ? true : '请输入 1–200 个字', confirmButtonText: '确定处理', cancelButtonText: '取消' }); batchLoading.value = true; const { data } = await batchOrderAction({ ids: selectedOrderIds.value, action, reason: approved ? prompt.value : undefined }); ElMessage.success(`已处理 ${data.changed || 0} 条，跳过 ${data.skipped?.length || 0} 条`); await loadState(); if (activeTab.value === 'orders') await loadOrderPage() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '批量处理失败') } finally { batchLoading.value = false } }
async function loadOrderPage() { try { const { data } = await getKtvOrders({ keyword: orderPage.keyword, status: orderPage.status, room: orderPage.room, supplierId: orderPage.supplierId, paid: orderPage.paid, paymentMode: orderPage.paymentMode, refundStatus: orderPage.refundStatus, minTotalCents: toCents(orderPage.minTotal), maxTotalCents: toCents(orderPage.maxTotal), startTime: orderPage.timeRange?.[0] || '', endTime: orderPage.timeRange?.[1] || '', page: orderPage.page, pageSize: orderPage.pageSize }); orderPage.items = data.items || []; orderPage.total = Number(data.total || 0); state.orderTotal = orderPage.total; selectedOrderIds.value = [] } catch (error) { orderPage.items = []; orderPage.total = 0; if ([401, 403].includes(error.response?.status)) throw error; ElMessage.error(error.response?.data?.message || '订单加载失败') } }
async function loadPaymentPage() { try { const { data } = await getKtvOrders({ keyword: appliedPaymentFilter.keyword, paid: true, paymentMode: appliedPaymentFilter.mode, refundStatus: appliedPaymentFilter.refundStatus, page: paymentPage.page, pageSize: paymentPage.pageSize }); paymentPage.items = data.items || []; paymentPage.total = Number(data.total || 0) } catch (error) { paymentPage.items = []; paymentPage.total = 0; if ([401, 403].includes(error.response?.status)) throw error; ElMessage.error(error.response?.data?.message || '支付记录加载失败') } }
 function selectTab(tab) { activeTab.value = tab === 'permissions' ? 'accounts' : tab; resetListFilter(); resetPaymentFilter(); selectedOrderIds.value = []; if (tab === 'orders') { orderPage.page = 1; loadOrderPage() } else if (tab === 'payments') { paymentPage.page = 1; loadPaymentPage() } }; function searchOrders() { orderPage.page = 1; loadOrderPage() }; function resetOrderSearch() { Object.assign(orderPage, { keyword: '', status: '', room: '', supplierId: '', paid: undefined, paymentMode: '', refundStatus: '', minTotal: undefined, maxTotal: undefined, timeRange: [], page: 1 }); loadOrderPage() }; function applyListFilter() { Object.assign(appliedListFilter, listFilter) }; function resetListFilter() { Object.assign(listFilter, { keyword: '', status: '' }); Object.assign(appliedListFilter, { keyword: '', status: '' }) }; function applyPaymentFilter() { Object.assign(appliedPaymentFilter, paymentFilter); paymentPage.page = 1; loadPaymentPage() }; function resetPaymentFilter() { Object.assign(paymentFilter, { keyword: '', mode: '', refundStatus: '' }); Object.assign(appliedPaymentFilter, { keyword: '', mode: '', refundStatus: '' }); paymentPage.page = 1; if (activeTab.value === 'payments') loadPaymentPage() }
async function loadState() { try { const { data } = await getKtvState(); if (data.role !== 'admin') throw new Error('当前账号不是管理员'); Object.assign(state, data); if (activeTab.value === 'orders') await loadOrderPage(); else if (activeTab.value === 'payments') await loadPaymentPage(); else { const { data: totals } = await getKtvOrders({ page: 1, pageSize: 1 }); state.orderTotal = Number(totals.total || 0) } } catch (error) { if ([401, 403].includes(error.response?.status) || error.message === '当前账号不是管理员') { localStorage.removeItem('ktv-token'); localStorage.removeItem('ktv-role'); router.replace('/login') } else ElMessage.error(error.response?.data?.message || '数据加载失败') } }
function editRow(row) { const kind = activeTab.value === 'foods' ? 'food' : activeTab.value === 'rooms' ? 'room' : 'account'; dialog.kind = kind; dialog.title = `编辑${kind === 'food' ? '餐品' : kind === 'room' ? '包厢' : '外包账号'}`; dialog.form = { ...row }; dialog.originalId = row.id; dialog.editing = true; dialog.open = true }; function openRoom() { dialog.kind = 'room'; dialog.title = '新增包厢'; dialog.form = { id: '', bound: true, version: 0 }; dialog.originalId = ''; dialog.editing = false; dialog.open = true }; function openFood() { dialog.kind = 'food'; dialog.title = '新增餐品'; dialog.form = { id: `food-${Date.now().toString(36)}`, name: '', category: categories.value[0] || '主食', price: 0.01, customImage: '', image: 'chicken', description: '', onSale: true, version: 0 }; dialog.originalId = ''; dialog.editing = false; dialog.open = true }; function openCategory() { categoryDialog.form.name = ''; categoryDialog.open = true }; function openAccount() { dialog.kind = 'account'; dialog.title = '新增外包账号'; dialog.form = { name: '', password: '', enabled: true, process: true, deliver: true, version: 0 }; dialog.originalId = ''; dialog.editing = false; dialog.open = true }
async function saveRow() { const form = dialog.form || {}; let roomId = ''; let accountPayload = null; if (dialog.kind === 'food' && ((!dialog.editing && !/^food-[A-Za-z0-9-]{1,50}$/.test(String(form.id || ''))) || !String(form.name || '').trim() || !String(form.category || '').trim() || !(Number(form.price) > 0))) return ElMessage.warning('请填写有效的餐品编号、名称、分类和售价'); if (dialog.kind === 'category' && !String(form.name || '').trim()) return ElMessage.warning('请输入分类名称'); if (dialog.kind === 'room') { roomId = String(form.id || '').trim().toUpperCase(); if (!/^[A-Z0-9一-龥-]{1,12}$/.test(roomId)) return ElMessage.warning('包厢编号仅支持大写字母、数字、中文和短横线'); dialog.form = { ...form, id: roomId }; } if (dialog.kind === 'account') { const accountName = String(form.name || '').trim(); if (!accountName || (!dialog.editing && String(form.password || '').length < 12)) return ElMessage.warning(dialog.editing ? '请输入账号名称' : '新账号密码至少 12 位'); accountPayload = { ...form, name: accountName }; if (dialog.editing && !String(accountPayload.password || '')) delete accountPayload.password; dialog.form = accountPayload; } dialog.saving = true; try { if (dialog.kind === 'food') await updateProduct(dialog.form.id, dialog.form); else if (dialog.kind === 'category') await createCategory({ name: dialog.form.name }); else if (dialog.kind === 'room') await updateRoom(roomId, dialog.form, String(dialog.originalId || roomId).trim().toUpperCase()); else if (dialog.kind === 'account' && dialog.form.id) await updateAccount(dialog.form.id, dialog.form); else if (dialog.kind === 'account') await createAccount(dialog.form); dialog.open = false; ElMessage.success(dialog.kind === 'category' ? '分类已新增' : '保存成功'); } catch (error) { ElMessage.error(apiErrorMessage(error, '保存失败')); return } finally { dialog.saving = false } try { await loadState() } catch (error) { ElMessage.error(apiErrorMessage(error, '数据刷新失败')) } }; async function saveCategory() { const name = String(categoryDialog.form.name || '').trim(); if (!/^[一-龥A-Za-z0-9 _-]{1,20}$/.test(name)) return ElMessage.warning('分类名称为 1–20 个中文、字母、数字、空格或短横线'); categoryDialog.saving = true; try { await createCategory({ name }); categoryDialog.form.name = ''; ElMessage.success('分类已新增'); await loadState() } catch (error) { ElMessage.error(apiErrorMessage(error, '分类保存失败')) } finally { categoryDialog.saving = false } }; async function removeProduct(row) { try { await ElMessageBox.confirm('确认删除餐品“' + (row.name || row.id) + '”？删除后不可恢复。', '删除餐品', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteProduct(row.id); ElMessage.success('餐品已删除'); await loadState() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(apiErrorMessage(error, '删除餐品失败')) } }
async function removeRoom(row) { try { await ElMessageBox.confirm('确认删除包厢“' + row.id + '”？请确保包厢已停用且没有进行中订单。', '删除包厢', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteRoom(row.id); ElMessage.success('包厢已删除'); await loadState() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '删除包厢失败') } }
async function removeAccount(row) { try { await ElMessageBox.confirm('确认删除账号“' + (row.name || row.id) + '”？请先完成或转派进行中订单。', '删除外包账号', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteAccount(row.id); ElMessage.success('外包账号已删除'); await loadState() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '删除账号失败') } }
async function renameCategoryRow(name) { try { const prompt = await ElMessageBox.prompt('请输入新的分类名称', '重命名分类', { inputValue: name, confirmButtonText: '保存', cancelButtonText: '取消', inputValidator: value => /^[一-龥A-Za-z0-9 _-]{1,20}$/.test(String(value || '').trim()) ? true : '分类名称为 1–20 个中文、字母、数字、空格或短横线' }); await renameCategoryApi(name, { name: prompt.value.trim() }); ElMessage.success('分类已重命名'); await loadState() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '分类重命名失败') } }async function removeCategory(name) { try { await ElMessageBox.confirm('确认删除分类“' + name + '”？', '删除分类', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteCategory(name); ElMessage.success('分类已删除'); await loadState() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '删除分类失败') } }async function toggleProduct(row) { try { await updateProduct(row.id, { ...row, onSale: !row.onSale }); ElMessage.success(row.onSale ? '餐品已下架' : '餐品已上架'); await loadState() } catch (error) { ElMessage.error(error.response?.data?.message || '状态修改失败') } }
async function showRoomQr(room) { if (!room.bound) return ElMessage.warning('请先启用包厢'); try { qr.room = room.id; qr.type = 'mini'; const { data } = await generateRoomQRCode(room.id, { type: qr.type }); qr.url = data.image || data.qrcodeUrl || data.url; if (!qr.url) throw new Error('二维码内容为空，请检查微信小程序配置'); qr.open = true; await loadState() } catch (error) { ElMessage.error(error.response?.data?.message || '二维码生成失败，请检查微信小程序配置') } }; async function switchQrType() { try { const { data } = await generateRoomQRCode(qr.room, { type: qr.type }); qr.url = data.image || data.qrcodeUrl || data.url } catch (error) { ElMessage.error(error.response?.data?.message || '二维码生成失败') } }; async function regenerateQr() { try { await ElMessageBox.confirm('重新生成后，旧二维码将失效；停用包厢后不能下单。是否继续？', '重新生成二维码', { type: 'warning', confirmButtonText: '继续生成', cancelButtonText: '取消' }); const { data } = await generateRoomQRCode(qr.room, { type: qr.type, rotate: true }); qr.url = data.image || data.qrcodeUrl || data.url; await loadState(); ElMessage.success('二维码已重新生成') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '二维码生成失败') } }
function triggerUpload() { uploadInput.value?.click() }
async function normalizeImageFile(file) { const name = String(file.name || '').toLowerCase(); const type = String(file.type || '').toLowerCase(); if (['image/png', 'image/jpeg'].includes(type) || /\.(png|jpe?g)$/.test(name)) return file; return new Promise((resolve, reject) => { const source = URL.createObjectURL(file); const image = new Image(); image.onload = () => { try { const max = 4096; const scale = Math.min(1, max / Math.max(image.naturalWidth || image.width, image.naturalHeight || image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round((image.naturalWidth || image.width) * scale)); canvas.height = Math.max(1, Math.round((image.naturalHeight || image.height) * scale)); const context = canvas.getContext('2d'); context.drawImage(image, 0, 0, canvas.width, canvas.height); canvas.toBlob(blob => { URL.revokeObjectURL(source); if (!blob) return reject(new Error('图片格式无法转换，请选择 PNG 或 JPG')); resolve(new File([blob], `${String(file.name || '图片').replace(/\.[^.]+$/, '')}.png`, { type: 'image/png' })) }, 'image/png') } catch (error) { URL.revokeObjectURL(source); reject(error) } }; image.onerror = () => { URL.revokeObjectURL(source); reject(new Error('图片格式无法读取，请选择 PNG、JPG 或常见图片格式')) }; image.src = source }) }
async function handleUpload(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 8 * 1024 * 1024) { ElMessage.error('图片不能超过 8 MB'); event.target.value = ''; return } try { const uploadFile = await normalizeImageFile(file); if (uploadFile.size > 2 * 1024 * 1024) throw new Error('图片处理后超过 2 MB，请压缩后再上传'); const { data } = await uploadKtvImage(uploadFile); dialog.form.customImage = data.url; ElMessage.success('图片上传成功') } catch (error) { ElMessage.error(apiErrorMessage(error, '图片上传失败')) } finally { event.target.value = '' } }
async function openOrderDetail(id) { detail.open = true; detail.loading = true; detail.order = {}; detail.reassignSupplierId = ''; try { const { data } = await getKtvOrderDetail(id); detail.order = data.order || {}; detail.reassignSupplierId = detail.order.supplierId || '' } catch (error) { detail.open = false; ElMessage.error(error.response?.data?.message || '订单详情加载失败') } finally { detail.loading = false } }
async function reassignDetail() { const target = String(detail.reassignSupplierId || '').trim(); if (!target || target === detail.order.supplierId) return ElMessage.warning('请选择不同的接单账号'); try { const prompt = await ElMessageBox.prompt('请输入转派原因', '转派订单', { inputValue: '管理员调整接单账号', confirmButtonText: '确认转派', cancelButtonText: '取消', inputValidator: value => value && value.trim().length <= 200 ? true : '请输入 1–200 个字' }); await reassignKtvOrder(detail.order.id, { supplierId: target, reason: prompt.value.trim(), version: detail.order.version }); ElMessage.success('订单已转派'); await loadState(); await openOrderDetail(detail.order.id) } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '订单转派失败') } }
async function reviewRefundRequest(order, approved) { try { const prompt = await ElMessageBox.prompt(approved ? '请输入同意退款说明' : '请输入拒绝退款原因', approved ? '退款审批' : '拒绝退款', { inputValue: approved ? '管理员同意退款' : '退款申请不符合条件', inputValidator: value => value && value.trim().length <= 200 ? true : '请输入 1–200 个字', confirmButtonText: '确定', cancelButtonText: '取消' }); await reviewRefund(order.id, { approved, reason: prompt.value }); ElMessage.success(approved ? '已同意退款' : '已拒绝退款'); await loadState(); if (activeTab.value === 'orders') await loadOrderPage(); if (detail.open) await openOrderDetail(order.id) } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.response?.data?.message || '退款审批失败') } }; async function logout() { try { await ktvLogout() } finally { localStorage.removeItem('ktv-token'); localStorage.removeItem('ktv-role'); router.replace('/login') } }
onMounted(() => { now.value = formatNow(); timer = setInterval(() => { now.value = formatNow() }, 1000); loadState() }); onUnmounted(() => clearInterval(timer))
